const PROMPTS = {"talent": {"version": "v5", "model": "openai/gpt-5.6-luna", "system": "Level scale (LinkedIn's six levels):\n- internship: student or intern.\n- entry: about 0-2 years; scoped tasks with guidance (Junior, Graduate, Engineer I).\n- associate: about 1-3 years; works independently on defined work (Associate, Engineer II).\n- mid-senior: about 3-10 years; owns projects or systems end to end, may mentor (Senior, Staff, Lead, plain titles with experience).\n- director: manages managers or owns a function, typically 10+ years.\n- executive: VP, C-level, founder or co-founder roles.\nFounder or C-level titles at very small or very young companies are graded by actual scope and years, not by title.\n\nYou read a candidate's LinkedIn profile for job matching.\n- level: grade on the scale using the computed years and actual scope.\n- title_family: the kind of work they actually practise.\n- plain_current_title: the current role as a plain title employers post, without founder, co-founder or C-level words.\n- related_titles: up to 3 specific titles (two or more words) employers post for this kind of role at this level, without founder or C-level words.\n- skills: at most 20, canonical common names. evidence = work_history only if a position description names it; otherwise listed_only.\n- industries: the industries of the candidate's EMPLOYERS only, from the fixed list: what each employer itself sells or does, judged from the company name and position description. Do not add the industries of customers they sold to or served. Usually one industry per employer.", "schema_name": "talent_read", "properties": {"level": {"type": "string", "enum": ["internship", "entry", "associate", "mid-senior", "director", "executive"]}, "level_evidence": {"type": "string"}, "title_family": {"type": "string", "enum": ["software_engineering", "frontend", "backend", "fullstack", "mobile", "ml_ai_engineering", "data_engineering", "data_science_analytics", "devops_infra_sre", "security", "qa_testing", "engineering_management", "product_management", "design", "founder_executive", "sales_gtm", "marketing", "operations", "finance_accounting", "consulting", "research", "other"]}, "plain_current_title": {"type": "string"}, "related_titles": {"type": "array", "items": {"type": "string"}}, "skills": {"type": "array", "items": {"type": "object", "properties": {"name": {"type": "string"}, "evidence": {"type": "string", "enum": ["work_history", "listed_only"]}}, "required": ["name", "evidence"], "additionalProperties": false}}, "industries": {"type": "array", "items": {"type": "string", "enum": ["software_saas", "fintech_payments", "banking_lending", "insurance", "investment_asset_management", "healthcare_providers", "medical_devices", "pharma_biotech_life_sciences", "government_defense", "education", "retail_ecommerce", "consumer_goods_food_beverage", "manufacturing_industrial", "automotive", "energy_utilities", "real_estate_construction", "logistics_supply_chain", "media_advertising_marketing_agencies", "telecom", "hospitality_travel", "legal", "consulting_professional_services", "nonprofit", "crypto_web3", "gaming_entertainment", "hardware_semiconductors", "hr_staffing", "data_ai_platforms", "cybersecurity", "other"]}}}}, "job": {"version": "v5", "model": "openai/gpt-5.6-luna", "system": "Level scale (LinkedIn's six levels):\n- internship: student or intern.\n- entry: about 0-2 years; scoped tasks with guidance (Junior, Graduate, Engineer I).\n- associate: about 1-3 years; works independently on defined work (Associate, Engineer II).\n- mid-senior: about 3-10 years; owns projects or systems end to end, may mentor (Senior, Staff, Lead, plain titles with experience).\n- director: manages managers or owns a function, typically 10+ years.\n- executive: VP, C-level, founder or co-founder roles.\n\nYou read one LinkedIn job posting and return facts. Quotes must be copied exactly from the text.\n- agency: is the poster a staffing/recruitment agency, job board, aggregator or marketplace, or reposting for a different employer? 'No agencies' means a direct employer.\n- named_employer: if the text says the role is at a specific company other than the poster, give that company's name; otherwise empty string.\n- title_family: the kind of job. Use 'executive'-style family founder_executive for founder/CEO/C-level openings.\n- level: grade the role on the scale. Founder, co-founder, CEO and C-level openings are executive.\n- experience_paths: the ways a candidate can qualify on experience. Each path lists everything that must hold together, so its min_years is the LARGEST number in it ('8+ years, with 3 in X' is one path of 8; '6+ years of A, 4+ of B' is one path of 6). Separate paths are alternatives joined by OR ('9 years, or 7 with a Bachelor's'). 'Or equivalent experience' without a number is not a path. Empty list if no years are stated.\n- sponsorship: no_sponsorship if it won't sponsor or requires existing US authorization, citizenship or clearance; offers if it says it sponsors; otherwise not_stated.\n- must_have_skills: at most 8, the most central required technical skills, canonical common names ('react', 'python', 'aws', 'llm'). nice_to_have_skills: at most 6.\n- funding_quote: a verbatim quote stating a funding round or investors, or empty string.\n- required_industries: industries from the fixed list where PRIOR EXPERIENCE is stated as REQUIRED for the candidate (e.g. '5+ years selling medical devices', 'must have agency experience', 'insurance license and personal lines experience required'). Do NOT include the employer's own industry unless the posting requires prior experience in it. Do NOT include industries that are only preferred, a plus, or nice to have. Empty list if none.\n- required_industry_quote: the exact sentence that states the requirement, or empty string.", "schema_name": "job_read", "properties": {"agency": {"type": "string", "enum": ["employer", "agency", "unsure"]}, "agency_quote": {"type": "string"}, "named_employer": {"type": "string"}, "title_family": {"type": "string", "enum": ["software_engineering", "frontend", "backend", "fullstack", "mobile", "ml_ai_engineering", "data_engineering", "data_science_analytics", "devops_infra_sre", "security", "qa_testing", "engineering_management", "product_management", "design", "founder_executive", "sales_gtm", "marketing", "operations", "finance_accounting", "consulting", "research", "other"]}, "level": {"type": "string", "enum": ["internship", "entry", "associate", "mid-senior", "director", "executive"]}, "level_quote": {"type": "string"}, "experience_paths": {"type": "array", "items": {"type": "object", "properties": {"min_years": {"type": "integer"}, "condition": {"type": "string"}, "quote": {"type": "string"}}, "required": ["min_years", "condition", "quote"], "additionalProperties": false}}, "sponsorship": {"type": "string", "enum": ["no_sponsorship", "offers", "not_stated"]}, "sponsorship_quote": {"type": "string"}, "must_have_skills": {"type": "array", "items": {"type": "string"}}, "nice_to_have_skills": {"type": "array", "items": {"type": "string"}}, "funding_quote": {"type": "string"}, "required_industries": {"type": "array", "items": {"type": "string", "enum": ["software_saas", "fintech_payments", "banking_lending", "insurance", "investment_asset_management", "healthcare_providers", "medical_devices", "pharma_biotech_life_sciences", "government_defense", "education", "retail_ecommerce", "consumer_goods_food_beverage", "manufacturing_industrial", "automotive", "energy_utilities", "real_estate_construction", "logistics_supply_chain", "media_advertising_marketing_agencies", "telecom", "hospitality_travel", "legal", "consulting_professional_services", "nonprofit", "crypto_web3", "gaming_entertainment", "hardware_semiconductors", "hr_staffing", "data_ai_platforms", "cybersecurity", "other"]}}, "required_industry_quote": {"type": "string"}}}};

// W2 step 3 (Filter): read each new posting once (5 at a time), then check companies for startup stage.
const { talent_id, run_id } = $input.first().json;
await runStep(run_id, 'filter', async ctx => {
  const todo = await rpc('jobs_to_read', { p_talent: talent_id });
  await ctx.log(`Reading ${todo.length} postings, 5 at a time`, true);
  const facts = []; let failed = 0, done = 0;
  const jobText = j => `Title: ${py(j.title)}\nCompany: ${py(j.company_name)} (${py(j.employee_count)} employees)\nCompany description: ${j.company_description || ''}\nLinkedIn level: ${j.experience_level || 'not given'}\n\n${j.description || ''}`;
  for (let i = 0; i < todo.length; i += 5) {
    const batch = todo.slice(i, i + 5);
    const res = await Promise.allSettled(batch.map(j => llm(PROMPTS.job, jobText(j))));
    res.forEach((r, k) => {
      const j = batch[k];
      if (r.status !== 'fulfilled') { failed++; return; }
      const o = r.value.out;
      facts.push({ job_id: j.job_id, content_hash: j.content_hash, prompt_version: PROMPTS.job.version, model: PROMPTS.job.model,
        agency: o.agency, agency_quote: o.agency_quote, named_employer: o.named_employer, role_family: o.title_family, level: o.level,
        level_quote: o.level_quote, experience_paths: o.experience_paths, sponsorship: o.sponsorship, sponsorship_quote: o.sponsorship_quote,
        must_have_skills: o.must_have_skills, nice_to_have_skills: o.nice_to_have_skills, required_industries: o.required_industries || [],
        required_industry_quote: o.required_industry_quote, funding_quote: o.funding_quote, raw_response: o });
    });
    done += batch.length;
    await ctx.progress(`Reading ${done} of ${todo.length} postings…`, { read: done - failed, failed, total: todo.length });
  }
  if (facts.length) await sb('POST', 'job_facts?on_conflict=job_id,content_hash,prompt_version,model', facts, 'resolution=ignore-duplicates');
  await ctx.log(`Read ${facts.length} of ${todo.length}${failed ? ` · ${failed} couldn't be read, will retry next run` : ''}`);
  const comps = await rpc('companies_to_enrich', { p_talent: talent_id });
  let enriched = 0;
  if (comps.length) {
    await ctx.log(`Checking ${comps.length} new companies`, true);
    try {
      const { items } = await apify('linkedin-company', { companies: comps.map(c => c.linkedin_url) }, ctx);
      enriched = await rpc('save_company_details', { p_items: items });
    } catch (e) { await ctx.log(`Company check failed (${e.message}); stage stays unknown for now`); }
  }
  const verified = await rpc('apply_funding_quotes', { p_talent: talent_id });
  await ctx.log(`Companies updated: ${enriched} · funding rounds found in postings: ${verified}`);
  return {
    summary: `${facts.length} postings read${failed ? ` · ${failed} couldn't be read, retrying next run` : ''} · ${comps.length} new companies checked`,
    details: [`Postings already read before (same text): skipped`, `Startup stage: ${verified} from funding rounds quoted in postings, the rest inferred from company data`],
    counts: { read: facts.length, failed, total: todo.length, companies: comps.length, verified_stages: verified },
  };
});
